import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学日报 | 2026年9月4日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-09-04.md","filePath":"science-log/src/science-daily/2026-09-04.md"}'),g={name:"science-log/src/science-daily/2026-09-04.md"};function e(a,t,i,u,c,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="🔬-科学日报-2026年9月4日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年9月4日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年9月4日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年9月4日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：重建版简讯（事后重建，共 10 条：科学前沿 5 + AI 前沿 5） 分析日期：2026-09-04 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-失聪者大脑的视网膜拓扑重映射-资源再分配而非地图扩张" tabindex="-1">1. 失聪者大脑的视网膜拓扑重映射：资源再分配而非地图扩张 <a class="header-anchor" href="#_1-失聪者大脑的视网膜拓扑重映射-资源再分配而非地图扩张" aria-label="Permalink to &quot;1. 失聪者大脑的视网膜拓扑重映射：资源再分配而非地图扩张&quot;">​</a></h3><p><strong>原文</strong>：早期深度失聪成人的初级视皮层与丘脑外侧膝状体中，远周边视野表征更大，而中央视野表征更小，两结构总体积不变——神经资源发生再分配。</p><p><strong>深度扩展</strong>：</p><p>这项工作由英国<strong>约克大学心理学系与约克神经影像中心</strong>的 <strong>Alexandra T. Levine、Alex R. Wade</strong> 团队完成，2026-09-04 发表于《PNAS》（DOI: 10.1073/pnas.2532413123）。团队招募 <strong>16 名早发深度失聪成人</strong>与 <strong>16 名年龄匹配的听力对照</strong>，用<strong>功能磁共振（fMRI）<strong>做</strong>视网膜拓扑（retinotopic）视野映射</strong>——即让被试观看缓慢移动的视野刺激，逐体素恢复其&quot;感受野&quot;在视野中的位置，从而把 V1、LGN 的<strong>视野表征面积</strong>量化出来。</p><p><strong>关键数字与结论</strong>：失聪组在 <strong>V1</strong> 与 <strong>LGN</strong> 中<strong>远周边视野（far-peripheral）的皮层表征显著更大</strong>；但两结构的<strong>总体积两组无差异</strong>，且失聪组的<strong>中央视野表征更小</strong>。这排除了&quot;视觉皮层整体变大&quot;的简单解释，指向<strong>同一皮层预算内的按需再分配</strong>：发育期对周边视野的需求更高（失聪者依赖周边视觉读唇、注意侧后方手势与危险），皮层就把中央区的资源<strong>调拨</strong>给周边区。</p><p><strong>为什么重要</strong>：它把&quot;感觉剥夺导致跨模态可塑性&quot;从行为层面推到<strong>丘脑—皮层的结构层面</strong>，且给出了一个可证伪的强约束——<strong>总量守恒下的重分配</strong>。这意味着可塑性的资源是有限的，任何一处的增强都可能以另一处为代价。对<strong>人工系统</strong>而言，这正是&quot;容量分配&quot;问题的一个天然生物实例。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code> 中感觉代偿与皮层可塑性主题直接相连；其&quot;总量守恒、按需重分配&quot;的逻辑，与 <code>topics/ai-system-architecture/llm-scaling-limits.md</code> 讨论的<strong>固定容量下的分配</strong>同构。</p><hr><h3 id="_2-一个氨基酸改写热感知-trpa1-单点突变与卵生胚胎耐高温" tabindex="-1">2. 一个氨基酸改写热感知：TRPA1 单点突变与卵生胚胎耐高温 <a class="header-anchor" href="#_2-一个氨基酸改写热感知-trpa1-单点突变与卵生胚胎耐高温" aria-label="Permalink to &quot;2. 一个氨基酸改写热感知：TRPA1 单点突变与卵生胚胎耐高温&quot;">​</a></h3><p><strong>原文</strong>：TRPA1 孔域一个氨基酸在合弓类—双孔类分化时改变其热敏感性；保留祖先残基的卵生脊椎动物其 TRPA1 被热激活、保护胚胎，哺乳动物则因天门冬氨酸降低热响应。</p><p><strong>深度扩展</strong>：</p><p>研究由<strong>复旦大学生命科学学院 / 中科院动物研究所 / 东北林业大学</strong>等团队合作完成，2026-09-04 发表于《Science Advances》（DOI: 10.1126/sciadv.aee3948）。核心是一个跨越数亿年的<strong>单点突变</strong>：在 <strong>TRPA1</strong> 离子通道的<strong>孔域（pore domain）</strong>，一个氨基酸的改变发生在大约<strong>合弓类（synapsid，通向哺乳动物）与双孔类（diapsid，通向爬行类/鸟类）分道</strong>之际。</p><p><strong>机制链</strong>：保留<strong>祖先残基</strong>的卵生脊椎动物，其 TRPA1 被<strong>热激活</strong>——高温下通道开放、<strong>Ca²⁺ 内流</strong>，触发转录因子 <strong>SP1 入核</strong>，进而激活 <strong>CADM1 与 MDGA1</strong> 两个黏附/突触相关基因。这一通路在胚胎期支撑<strong>背根神经节（DRG）轴突生长</strong>与<strong>髓鞘化</strong>：若<strong>阻断热激活的 TRPA1</strong>，则轴突生长受损、髓鞘破坏，孵化时出现<strong>肢体无力</strong>。相反，哺乳动物谱系中被选择的<strong>天门冬氨酸</strong>（aspartate）<strong>降低了热响应</strong>，使通道对热的敏感性下降。</p><p><strong>为什么重要</strong>：它把&quot;物种特异的温度适应&quot;落到<strong>一个可指认的残基</strong>，并给出了一个反直觉的<strong>发育学角色</strong>——TRPA1 不只是成体感受器，还是<strong>胚胎热胁迫下的保护开关</strong>。一个突变，把离子通道的演化与<strong>胚胎存活</strong>直接绑定。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 中离子通道 / 钙信号主题相连；其&quot;单点突变重写功能阈值&quot;的逻辑可对照 <code>topics/physics/index.md</code> 中的相变/阈值思想——<strong>参数的微小移动即可跨越功能分界</strong>。</p><hr><h3 id="_3-来那卡帕韦如何-掰碎-hiv-衣壳-两步断裂与应力—应变模型" tabindex="-1">3. 来那卡帕韦如何&quot;掰碎&quot;HIV 衣壳：两步断裂与应力—应变模型 <a class="header-anchor" href="#_3-来那卡帕韦如何-掰碎-hiv-衣壳-两步断裂与应力—应变模型" aria-label="Permalink to &quot;3. 来那卡帕韦如何&quot;掰碎&quot;HIV 衣壳：两步断裂与应力—应变模型&quot;">​</a></h3><p><strong>原文</strong>：来那卡帕韦是 HIV-1 衣壳的变构调节剂，分两步瓦解衣壳的富勒烯锥结构——先在高曲率纬线处破裂，随后壳体主体出现裂隙，并改变亚基间非共价键、降低局部晶格曲率。</p><p><strong>深度扩展</strong>：</p><p>研究由美国<strong>犹他大学 Spencer Fox Eccles 医学院生物化学系</strong>的 <strong>Nayara F. B. dos Santos、Jacob A. Lewis、Mason Hansen、Miguel J. B. Pereira</strong> 等完成，2026-09-04 发表于《Science Advances》（DOI: 10.1126/sciadv.aed8384）。<strong>来那卡帕韦（lenacapavir, LEN）<strong>是当前最有前景的</strong>长效 HIV-1 衣壳抑制剂</strong>，用于治疗与预防，但&quot;它究竟如何让衣壳崩解&quot;一直不清。</p><p><strong>机制与数字</strong>：作者证明 LEN 是衣壳结构的<strong>变构调节剂</strong>，其破坏分<strong>两步</strong>：第一步在衣壳的<strong>高曲率&quot;纬线&quot;（declinations）处破裂</strong>——这是富勒烯锥几何上曲率最大、应变最集中的区位；第二步<strong>壳体主体（capsid body）出现裂隙</strong>。分子层面，LEN <strong>改变衣壳亚基之间的非共价键相互作用</strong>，并<strong>降低局部晶格曲率</strong>。为了把现象统一起来，作者提出<strong>应力—应变（stress-strain）模型</strong>：衣壳的可塑性来自晶格曲率分布，LEN 通过改变曲率把结构推过其<strong>弹性极限</strong>，进而削弱病毒的<strong>复制能力</strong>。</p><p><strong>为什么重要</strong>：在抗病毒领域，理解&quot;为什么有效&quot;直接决定<strong>耐药突变的预测</strong>与<strong>下一代药物的设计方向</strong>。把 LEN 定位为&quot;降低晶格曲率的变构调节剂&quot;，等于给衣壳靶点一个<strong>几何/力学的设计语言</strong>，而非仅仅&quot;某处结合某物&quot;。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的结构生物学与抗病毒主题相连；其&quot;几何曲率决定机械稳定性&quot;的逻辑，与 <code>topics/physics/index.md</code> 中<strong>几何 / 拓扑决定力学与稳定性</strong>的思想同构（如壳体、富勒烯、薄壳屈曲）。</p><hr><h3 id="_4-cirpin-扫描蛋白质宇宙的-圆周排列-拓扑近亲" tabindex="-1">4. CIRPIN：扫描蛋白质宇宙的&quot;圆周排列&quot;拓扑近亲 <a class="header-anchor" href="#_4-cirpin-扫描蛋白质宇宙的-圆周排列-拓扑近亲" aria-label="Permalink to &quot;4. CIRPIN：扫描蛋白质宇宙的&quot;圆周排列&quot;拓扑近亲&quot;">​</a></h3><p><strong>原文</strong>：MIT 团队提出对圆周排列不变的图神经网络 CIRPIN，建成含 1830 万蛋白对、覆盖 CATH 845 个独特拓扑的 CIRPIN-DB 数据库。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>MIT 生物系与 CSAIL</strong> 的 <strong>Aiden R. Kolodziej、S. Mazdak Abulnaga、Sergey Ovchinnikov</strong> 完成，2026-09-04 发表于《PNAS》（DOI: 10.1073/pnas.2605178123）。问题起于一个结构性盲点：深度学习结构搜索（如 Foldseek 类工具）能极快地在大库里找相似结构，却<strong>系统性漏掉&quot;拓扑重排&quot;关系</strong>，其中最典型的是<strong>圆周排列（circular permutation, CP）</strong>——两个蛋白<strong>结构几乎相同，只是 N/C 端的位置被挪动</strong>（相当于把同一串氨基酸换个起点读）。</p><p><strong>方法</strong>：CIRPIN 是一个<strong>对 CP 不变的图神经网络</strong>，关键在于<strong>数据增强</strong>——对蛋白<strong>合成圆周排列</strong>，逼迫模型学到<strong>对起终点位置不敏感的表示</strong>。这样它就能在 <strong>SCOP</strong> 与 <strong>AlphaFold Cluster Representatives</strong> 库中识别出被传统方法漏掉的结构近亲。</p><p><strong>关键数字</strong>：用 CIRPIN 建成的 <strong>CIRPIN-DB</strong> 含 <strong>1830 万对</strong>高度富集 CP 关系的蛋白对，覆盖 <strong>CATH 分类中的 845 个独特拓扑</strong>——作者称这是迄今<strong>最大、最全面</strong>的 CP 资源库。</p><p><strong>为什么重要</strong>：CP 不只是分类学趣闻——它意味着<strong>同一折叠可以换个&quot;读法&quot;实现不同功能</strong>，也在<strong>蛋白工程</strong>里被用来重接、稳定或赋予新功能。系统地把 CP 关系挖出来，等于给蛋白设计提供了一张**&quot;可互换的同源骨架&quot;地图**。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 蛋白结构与设计的主题相连；&quot;同一对象换一种表示即等价&quot;的逻辑，与 <code>topics/ai-system-architecture/index.md</code> 中**表示不变性（representation invariance）**的机器学习主线同构。</p><hr><h3 id="_5-渔业的-前置警报-产量骤降常先于种群崩溃约十年" tabindex="-1">5. 渔业的&quot;前置警报&quot;：产量骤降常先于种群崩溃约十年 <a class="header-anchor" href="#_5-渔业的-前置警报-产量骤降常先于种群崩溃约十年" aria-label="Permalink to &quot;5. 渔业的&quot;前置警报&quot;：产量骤降常先于种群崩溃约十年&quot;">​</a></h3><p><strong>原文</strong>：全球 315 个鱼种中超过四分之一检测到生产力突变；骤降在升温最快海区显著过度代表，且约四分之一发生突变的种群其生产力骤降早于崩溃约十年。</p><p><strong>深度扩展</strong>：</p><p>研究由法国<strong>蒙彼利埃演化科学研究所（ISEM）<strong>的 <strong>Mathieu Pélissié、Vincent Devictor、Vasilis Dakos</strong> 与美国威斯康星大学 / 康奈尔的 <strong>Olaf P. Jensen</strong> 合作完成，2026-09-04 发表于《Science Advances》（DOI: 10.1126/sciadv.aed7911）。背景是：气候变化与过捕会引发</strong>生产力的大幅、突然且持续的转变</strong>，但这类&quot;突变（abrupt shift）&quot;的<strong>全球发生率和驱动因子</strong>一直缺乏系统评估。</p><p><strong>关键数字</strong>：团队系统分类了全球<strong>机构评估渔业</strong>的<strong>种群生产力时间动态</strong>：在 <strong>315 个鱼种</strong>中，<strong>超过四分之一</strong>检测到生产力突变。<strong>骤降</strong>在<strong>升温最快</strong>的海区<strong>显著过度代表</strong>；<strong>骤增</strong>则更可能出现在<strong>捕捞强度较低</strong>处——把气候与捕捞两个驱动因子分离了出来。最关键的一条：在发生突变的种群中，约<strong>四分之一</strong>的<strong>生产力骤降早于种群崩溃约十年</strong>。</p><p><strong>为什么重要</strong>：这提供了一个<strong>可操作的前置预警信号</strong>。传统渔业管理盯的是<strong>生物量</strong>，往往在崩溃临界才反应；而<strong>生产力（补充量/增长率的异常下降）<strong>提前约十年发出信号，让管理者有窗口调整配额。它同时印证了复杂系统理论中的</strong>早期预警信号（early-warning signals）</strong>——临界点前常伴随方差与自相关的升高。</p><p><strong>跨主题关联</strong>：与 <code>topics/physics/index.md</code> 中的临界点 / 临界慢化（critical slowing down）主题相连，Dakos 本人正是早期预警信号领域的代表人物；其&quot;气候 + 人为压力共同越过阈值&quot;的结构，与 <code>topics/wind-energy/index.md</code> 里资源—气候耦合的思想呼应。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-把-kv-缓存塞进片内非易失存储-面向固定量程转换器的量化方案" tabindex="-1">6. 把 KV 缓存塞进片内非易失存储：面向固定量程转换器的量化方案 <a class="header-anchor" href="#_6-把-kv-缓存塞进片内非易失存储-面向固定量程转换器的量化方案" aria-label="Permalink to &quot;6. 把 KV 缓存塞进片内非易失存储：面向固定量程转换器的量化方案&quot;">​</a></h3><p><strong>原文</strong>：长上下文 LLM 解码受 KV 缓存带宽约束；现有 KV 量化（KIVI 附带约 25% 元数据、KVQuant 保留稀疏离群值）不适配密集片内 NVM，本文设计与该接口匹配的量化方案。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>Jiahao Zheng、Yifan Qin、Xiaobo Sharon Hu（圣母大学）、Yiyu Shi（圣母大学）</strong> 等完成，arXiv:2609.05764（2026）。问题设定很清楚：长上下文 LLM 解码的<strong>主导瓶颈是 KV 缓存</strong>——每个解码步都要<strong>完整读取</strong>整块 KV，因此解码是<strong>访存带宽受限</strong>的。一条激进路径是把<strong>量化后的 KV 缓存</strong>放进<strong>密集片内非易失存储（NVM）</strong>，从而彻底<strong>消除片外搬运</strong>。</p><p><strong>结构冲突</strong>：现有 KV 量化方法是为<strong>类 GPU 存储体系</strong>设计的，落到 NVM 上就出问题——<strong>KIVI</strong> 采用<strong>逐组（per-group）元数据</strong>，让存储量<strong>膨胀约 25%</strong>；<strong>KVQuant</strong> 保留<strong>稀疏的全精度离群值（outliers）</strong>，而<strong>密集阵列无法就地存放</strong>这些稀疏特例。换言之，<strong>量化逻辑与硬件接口不匹配</strong>。</p><p><strong>方案</strong>：本文先量化这些结构在<strong>固定量程转换器（fixed-range converters）<strong>之后的 NVM 上的代价，再设计</strong>与该接口匹配</strong>的量化：量化 KV 存于<strong>密集片内 NVM</strong>，只用一个<strong>小型静态模拟交叉阵列</strong>执行<strong>固定旋转（fixed rotation）</strong>（把能量集中到少数通道，便于固定量程量化），而<strong>注意力计算保留在片内数字逻辑</strong>。</p><p><strong>为什么重要</strong>：它体现了一条正在成型的<strong>软硬协同原则</strong>——<strong>量化方案必须服从存储接口，而不是反过来</strong>。当推理从&quot;模型问题&quot;变成&quot;系统问题&quot;，算法收益越来越取决于它能否与<strong>模拟/数字混合硬件的物理约束</strong>对齐。</p><p><strong>跨主题关联</strong>：直接关联 <code>topics/ai-system-architecture/llm-cache-pricing.md</code>（KV 缓存的成本与经济学）与 <code>topics/ai-system-architecture/llm-scaling-limits.md</code>（长上下文的系统瓶颈）。</p><hr><h3 id="_7-不改模型也能提升工具智能体-把-运行时挽具-当资源受限的选择问题" tabindex="-1">7. 不改模型也能提升工具智能体：把&quot;运行时挽具&quot;当资源受限的选择问题 <a class="header-anchor" href="#_7-不改模型也能提升工具智能体-把-运行时挽具-当资源受限的选择问题" aria-label="Permalink to &quot;7. 不改模型也能提升工具智能体：把&quot;运行时挽具&quot;当资源受限的选择问题&quot;">​</a></h3><p><strong>原文</strong>：把固定模型多轮工具智能体的提示与工具边界中间件优化形式化为资源受限的挽具选择，提出优化器无关协议并报告 RelLift95(B) 保守增益估计。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>Cen Mia Zhao、Haibo Ruan、Wenjie Chen、Pei-fen Tu、Usman Abbasi、Joel Hesch</strong> 等完成，arXiv:2609.05736（2026）。核心洞察：LLM 工具智能体<strong>可以不改模型、不重训</strong>，仅靠修改<strong>运行时挽具（harness）</strong>——提示、工具接口、中间件、状态处理与恢复逻辑——就获得提升。这被称为&quot;<strong>harness engineering</strong>&quot;，是 2026 年智能体工程的主战场之一。</p><p><strong>形式化</strong>：作者把问题定义为<strong>固定模型多轮工具智能体的&quot;资源受限挽具选择&quot;</strong>，并把搜索面<strong>刻意收窄</strong>到<strong>提示 + 工具边界中间件</strong>：编辑是<strong>工具边界上的受保护拦截（guarded intercepts）</strong>，而<strong>不是任意改写智能体执行逻辑</strong>——这一步很关键，它把&quot;调优&quot;限制在<strong>可审计、可回滚、不碰执行语义</strong>的范围内。</p><p><strong>评测协议</strong>：提出<strong>优化器无关</strong>的协议，报告<strong>平均留出增益、最差条件增益、可重复性、成本诊断</strong>，以及 <strong>RelLift95(B)</strong>——在预算 B 下所选挽具留出增益的<strong>保守（95% 下界）估计</strong>。作者用 <strong>PRISM</strong> 等优化器实例化：它<strong>聚类失败案例</strong>，再把修复<strong>路由到提示、工具边界中间件或二者的联合编辑面</strong>。</p><p><strong>为什么重要</strong>：智能体社区长期缺少<strong>可复现、带预算与置信下界</strong>的调优方法学。把&quot;改提示/中间件&quot;从经验玄学变成<strong>有搜索空间、有预算、有最差情况保证</strong>的选择问题，是让智能体工程<strong>可规模化</strong>的前提。</p><p><strong>跨主题关联</strong>：直接关联 <code>topics/ai-system-architecture/deepseek-harness-agent-runtime.md</code>（智能体运行时/挽具）与 <code>topics/ai-brain/index.md</code>（工具化知识系统）；其&quot;最差条件增益&quot;思路与 <code>topics/ai-system-architecture/llm-reasoning-verification-thermodynamic.md</code> 的可靠性取向呼应。</p><hr><h3 id="_8-谁来维护智能体技能-人类主导、ai-辅助的纵向研究" tabindex="-1">8. 谁来维护智能体技能？人类主导、AI 辅助的纵向研究 <a class="header-anchor" href="#_8-谁来维护智能体技能-人类主导、ai-辅助的纵向研究" aria-label="Permalink to &quot;8. 谁来维护智能体技能？人类主导、AI 辅助的纵向研究&quot;">​</a></h3><p><strong>原文</strong>：挖掘 5 个公开 AI 技能仓库 873 次提交、143 个技能文件、254 次实质性创建后编辑，发现技能维护的人—机分工才是被忽视的关键变量。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>Chen Shen、Estevam Hruschka</strong>（IBM Research）完成，arXiv:2609.05677（2026）。背景：<strong>终身学习的 LLM 智能体</strong>越来越依赖<strong>外部技能制品</strong>——通常是可移植的 <strong>Markdown 文件（如 SKILL.md）</strong>——来描述&quot;何时、如何&quot;使用某项能力。这些技能必须随工具与用法变化被<strong>修正、扩充与整合</strong>。</p><p><strong>方法</strong>：作者指出，近期&quot;自动技能策展&quot;的工作多以<strong>自动基线</strong>评估，<strong>把人类维护当作未测量的瓶颈</strong>。他们<strong>直接研究这一过程</strong>：挖掘 <strong>5 个公开 AI 技能仓库</strong>的<strong>完整提交历史</strong>（作者称这是对 AI 工具组织的<strong>有目的抽样</strong>），覆盖 <strong>873 次提交、143 个技能文件、254 次实质性的创建后编辑</strong>，时间跨 <strong>2025-10 至 2026-06</strong>；再用<strong>预注册（pre-registered）<strong>的</strong>治理 / 操作 / 触发证据</strong>编码簿，对每次编辑逐条编码——即&quot;谁改的、改了什么类型、由什么触发&quot;。</p><p><strong>结论</strong>：技能维护的<strong>人—机分工</strong>才是系统成功的关键变量；<strong>纯自动策展的评估高估了自动化程度</strong>，因为真正决定技能质量的编辑信号常来自人的<strong>触发与治理</strong>。</p><p><strong>为什么重要</strong>：它给&quot;智能体技能库&quot;这类新兴基础设施注入现实主义——技能不是一次性生成物，而是<strong>需要人类持续照看的活资产</strong>。对任何构建技能生态的系统（包括本知识库）都是直接的<strong>运维警示</strong>。</p><p><strong>跨主题关联</strong>：直接关联 <code>topics/ai-brain/knowledge-system-arsenal.md</code>（技能/工具库运维）与 <code>topics/ai-system-architecture/brain-self-evolution.md</code>（自进化 vs 人工治理）；其&quot;预注册编码簿&quot;方法论与 <code>topics/philosophy/epistemology.md</code> 的<strong>可证伪 / 可复现</strong>主题相连。</p><hr><h3 id="_9-ai-开发中的-偏差正常化-组织为何先天倾向漂向失败" tabindex="-1">9. AI 开发中的&quot;偏差正常化&quot;：组织为何先天倾向漂向失败 <a class="header-anchor" href="#_9-ai-开发中的-偏差正常化-组织为何先天倾向漂向失败" aria-label="Permalink to &quot;9. AI 开发中的&quot;偏差正常化&quot;：组织为何先天倾向漂向失败&quot;">​</a></h3><p><strong>原文</strong>：以挑战者号、三里岛、波音 737 MAX 为案例，识别失败前的共性结构机制，并映射到当代 AI 开发——现有安全基础设施的保护可能比看起来更少。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>Emilio Barkett、Alexander Kimpton、Daniel Graham、Yusuf Kundgol</strong> 完成，arXiv:2609.05749（2026）。它切入的是一个被主流 AI 安全叙事<strong>系统性忽略的层级</strong>：AI 风险研究<strong>压倒性地聚焦&quot;能力风险&quot;</strong>——系统过强、过自主、与人类价值错位；而<strong>组织层面</strong>——建造这些系统的机构<strong>是否本身就先天地漂向失败</strong>——关注极少。</p><p><strong>方法</strong>：作者借用社会学中**&quot;偏差正常化（normalization of deviance)&quot;<strong>这一经典概念（源自 Diane Vaughan 对挑战者号事故的研究）：在一个组织里，偏离安全规范的</strong>小偏差<strong>若反复未致灾，就会</strong>被逐步接受为新常态**，安全边际被一点点蚕食，直到某个普通扰动触发<strong>系统性失败</strong>。论文用三个案例——<strong>挑战者号航天飞机、三里岛核事故、波音 737 MAX 空难</strong>——提取每次失败前的<strong>共性结构机制</strong>，并把它们<strong>逐条映射到当代 AI 开发</strong>。</p><p><strong>核心论断</strong>：无论 AI 系统变得多强，建造它们的组织都面临<strong>与过往重大技术灾难相同的结构性动力学</strong>。由此推出一个尖锐结论：<strong>现有安全基础设施提供的保护，可能比它表面看起来要少</strong>——因为保护措施若被&quot;偏差正常化&quot;逐步掏空，形式上仍在、实效上已失。</p><p><strong>为什么重要</strong>：这把 AI 安全从**&quot;模型属性&quot;<strong>扩展到</strong>&quot;组织社会学&quot;<strong>：即使模型对齐做得再好的团队，也可能因</strong>组织漂移**而失效。它提示一条可操作结论——<strong>测量&quot;偏差是否被正常化&quot;</strong>（例如评估记录被搁置的频率、告警被静默的次数）本身应成为安全指标。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code> 中的 AI 治理/安全主线相连；其&quot;约束被逐步侵蚀直至崩溃&quot;的结构，与 <code>topics/ai-system-architecture/cognitive-atrophy-knowledge.md</code>（能力因约束消失而退化）同构，也与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的&quot;约束—涌现&quot;模式呼应。</p><hr><h3 id="_10-di-bench-为-企业智能体-自动生成领域数据智能基准" tabindex="-1">10. DI-Bench：为&quot;企业智能体&quot;自动生成领域数据智能基准 <a class="header-anchor" href="#_10-di-bench-为-企业智能体-自动生成领域数据智能基准" aria-label="Permalink to &quot;10. DI-Bench：为&quot;企业智能体&quot;自动生成领域数据智能基准&quot;">​</a></h3><p><strong>原文</strong>：DI-Bench 在数据表、维度、指标与文档之上构建制品链接图，经查询执行导出标准答案、再由 LLM 生成并验证题目，产出 731 题的企业数据智能基准。</p><p><strong>深度扩展</strong>：</p><p>研究由 <strong>Jiangyun Zhang、Kristen Surrao、Torpong Nitayanont、Yupei Zhang、Roopali Singh、Zhiyu Chen</strong> 等完成，arXiv:2609.05776（2026）。要评测<strong>企业智能体</strong>，就需要<strong>领域专用基准</strong>；但公开基准<strong>很少检验智能体能否把业务知识与解析计算结合起来</strong>，而人工构造这类基准<strong>极其昂贵</strong>。</p><p><strong>方法</strong>：作者提出 <strong>DI-Bench</strong>——一条为<strong>数据智能（data intelligence, DI）</strong>（即&quot;从海量企业数据中提取洞察&quot;的实践）自动生成<strong>真实基准</strong>的流水线。为逼近既需<strong>计算</strong>又需<strong>知识检索</strong>的真实 DI 任务，DI-Bench 在<strong>数据表、维度（dimensions）、指标（metrics）与文档</strong>之上构建<strong>制品链接图（artifact linkage graph）</strong>，据此生成<strong>同时涉及结构化数据与相关知识</strong>的问题。<strong>标准答案经查询执行（query execution）导出</strong>——这是关键的&quot;真值锚定&quot;，避免让 LLM 自己编答案；随后由 <strong>LLM 生成题目并做验证</strong>。</p><p><strong>关键数字</strong>：在两个公开数据集上，该流水线产出一个 <strong>731 题</strong>的基准，覆盖<strong>知识检索、解析计算</strong>等维度。</p><p><strong>为什么重要</strong>：它把&quot;企业级智能体评测&quot;从<strong>手工作坊</strong>变成<strong>可规模化生成的流水线</strong>，并用<strong>查询执行</strong>给真值上锁。对任何想落地企业智能体的团队，这是把&quot;能不能用&quot;从<strong>主观印象</strong>转为<strong>可复现度量</strong>的基础设施。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/bazaar-agentic-commerce.md</code>（智能体的商业落地）和 <code>topics/ai-system-architecture/ai-industry-2026-q3-knowledge.md</code>（企业 AI 知识）相连；其&quot;用执行结果锚定真值&quot;的思路与 <code>topics/ai-system-architecture/llm-reasoning-verification-thermodynamic.md</code>（推理验证）呼应。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-单点突变如何重写-阈值-——从-trpa1-到衣壳与渔业突变" tabindex="-1">机制一：单点突变如何重写&quot;阈值&quot;——从 TRPA1 到衣壳与渔业突变 <a class="header-anchor" href="#机制一-单点突变如何重写-阈值-——从-trpa1-到衣壳与渔业突变" aria-label="Permalink to &quot;机制一：单点突变如何重写&quot;阈值&quot;——从 TRPA1 到衣壳与渔业突变&quot;">​</a></h3><p>本期三条看似无关的工作共享同一个机制骨架：<strong>一个连续参数跨越某个阈值，就导致系统行为发生质变。</strong></p><p><strong>TRPA1（第 2 条）</strong> 给出最干净的例子。离子通道的<strong>热激活</strong>本质是一个<strong>热力学开关</strong>：通道在闭合态与开放态之间的自由能差 ΔG 随温度线性移动（ΔG(T) ≈ ΔH − TΔS）。当 ΔG 过零时，通道开放概率骤升——这就是&quot;阈值温度&quot;。TRPA1 <strong>孔域</strong>的一个氨基酸（祖先残基 vs 哺乳动物的天门冬氨酸）改变了局部静电/空间构象，从而<strong>平移了 ΔS 或 ΔH</strong>，等价于<strong>把阈值温度整体挪动</strong>。下游是一条清晰的<strong>信号级联</strong>：通道开放 → <strong>Ca²⁺ 内流</strong> → 钙依赖信号使转录因子 <strong>SP1 入核</strong> → 激活 <strong>CADM1 / MDGA1</strong> → 支撑<strong>背根神经节轴突生长与髓鞘化</strong>。于是&quot;一个残基&quot;通过<strong>平移阈值</strong>，改写了胚胎在高温下的存活概率——这是<strong>参数→阈值→表型</strong>的完整因果链。</p><p><strong>来那卡帕韦—HIV 衣壳（第 3 条）</strong> 是同一骨架的<strong>力学版本</strong>。富勒烯锥衣壳的<strong>稳定性由晶格曲率分布决定</strong>；LEN <strong>降低局部晶格曲率</strong>并<strong>改变亚基间非共价键</strong>，等价于<strong>移动了结构的弹性极限</strong>。当应力超过该极限，结构先在高曲率的&quot;纬线&quot;处（应力集中点）<strong>开裂</strong>，再<strong>主体断裂</strong>——这就是为什么破坏<strong>分两步</strong>：<strong>开裂总是从应变最大的区位启动</strong>，这与材料断裂力学中&quot;裂纹优先在应力集中处萌生&quot;完全一致。<strong>应力—应变模型</strong>因此不是修辞，而是把病毒衣壳当作<strong>一个可计算弹性极限的薄壳结构</strong>。</p><p><strong>渔业（第 5 条）</strong> 则是<strong>生态—经济耦合系统</strong>的阈值版本：<strong>生产力骤降</strong>早于<strong>种群崩溃约十年</strong>，说明系统在<strong>崩溃阈值</strong>之前就已<strong>越过某个更早的临界点</strong>（补给能力先垮，生物量后垮）。这正是**临界慢化（critical slowing down）**的宏观特征——系统临近临界点时，从扰动中恢复的速度变慢，方差与自相关升高，于是&quot;预警信号&quot;先于崩塌出现。</p><p><strong>统一机制</strong>：<strong>在梯度驱动下，系统先逼近临界点（预警征兆），越过阈值后发生不可逆的质变（相变 / 断裂 / 崩溃）。</strong> 三条超导型的例子覆盖了<strong>热力学、力学、生态学</strong>三个物理层，但<strong>参数→阈值→质变</strong>的骨架完全同构。</p><hr><h3 id="机制二-容量守恒下的-按需再分配-——从失聪者皮层到-nvm-上的-kv-缓存" tabindex="-1">机制二：容量守恒下的&quot;按需再分配&quot;——从失聪者皮层到 NVM 上的 KV 缓存 <a class="header-anchor" href="#机制二-容量守恒下的-按需再分配-——从失聪者皮层到-nvm-上的-kv-缓存" aria-label="Permalink to &quot;机制二：容量守恒下的&quot;按需再分配&quot;——从失聪者皮层到 NVM 上的 KV 缓存&quot;">​</a></h3><p>第二组机制要处理的是<strong>固定资源如何被最优分配</strong>。</p><p><strong>失聪者视觉重映射（第 1 条）</strong> 给出了一个<strong>生物学铁证</strong>：V1 与 LGN 的<strong>总体积两组无差异</strong>，但失聪组的<strong>远周边视野表征更大、中央视野表征更小</strong>。这说明皮层不是&quot;随便长&quot;，而是<strong>在总量守恒下按发育期需求重分配</strong>——对周边视野的高需求&quot;抢&quot;走了中央区的表征资源。其机制基础是<strong>活动依赖的竞争性可塑性</strong>：神经表征的边界由<strong>输入资源竞争</strong>动态划定，而非固定模板。</p><p><strong>KV 缓存量化（第 6 条）</strong> 是<strong>人工系统里同一个问题</strong>：片内 NVM 的容量与带宽是<strong>固定预算</strong>，如何放置量化后的 KV 才能最优？<strong>KIVI 的逐组元数据膨胀约 25%</strong>、<strong>KVQuant 的稀疏离群值无处存放</strong>，本质都是**&quot;开支&quot;吃掉了太多固定预算**——它们没有把<strong>存储结构的开销</strong>纳入总资源约束。本文的方案（密集 NVM + 固定旋转 + 片内数字注意力）则把<strong>资源在&quot;存储、旋转、计算&quot;三者间重新分配</strong>，与皮层&quot;在中央/周边之间重分配表征&quot;在<strong>约束优化</strong>的意义上完全同构。</p><p><strong>机制统一的推论</strong>：<strong>只要预算是守恒的，任何&quot;局部增强&quot;都必然要求别处的&quot;局部让渡&quot;。</strong> 这条约束同时是<strong>可证伪的</strong>：在皮层，它预测<strong>剥夺越多、重分配越极端</strong>，且任何&quot;某一视野区变大&quot;都应伴随另一区变小（总量不变）；在硬件，它预测<strong>任何声称&quot;零开销&quot;的量化方案</strong>，其收益要么来自<strong>别处让渡</strong>（如精度、带宽），要么来自<strong>偷换口径</strong>——<strong>没有免费的容量</strong>。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-阈值与几何——断裂、激活、崩溃都由-何处最先越界-决定" tabindex="-1">原理一：阈值与几何——断裂、激活、崩溃都由&quot;何处最先越界&quot;决定 <a class="header-anchor" href="#原理一-阈值与几何——断裂、激活、崩溃都由-何处最先越界-决定" aria-label="Permalink to &quot;原理一：阈值与几何——断裂、激活、崩溃都由&quot;何处最先越界&quot;决定&quot;">​</a></h3><p>本期反复出现的&quot;突变&quot;，其第一性原理可以归结为一句：<strong>系统的失效不是均匀发生的，而是从某个&quot;最脆弱区位&quot;启动的。</strong></p><p>看几何：衣壳是<strong>富勒烯锥</strong>，其<strong>高斯曲率</strong>在&quot;纬线&quot;（declinations）处最大。薄壳理论告诉我们，弯曲应变能密度正比于曲率——<strong>曲率越大处，单位面积储存的应变能越多</strong>。当外加或内生的应力增长，<strong>应变能密度最高的区位最先达到材料的断裂阈值</strong>，于是裂纹从那里萌生。这就是为什么 LEN 的破坏&quot;<strong>先在高曲率纬线处破裂、后壳体主体开裂</strong>&quot;——不是巧合，而是<strong>几何决定了失效的顺序</strong>。可推广为<strong>可证伪预测</strong>：任何富勒烯式封闭壳体（病毒衣壳、碳笼、脂质囊泡、薄壳穹顶）受均匀膨胀压力时，<strong>裂纹起点应集中在曲率极值处，且可通过改变曲率分布来移动起裂位置</strong>。</p><p>看热力学：TRPA1 的热激活是一个<strong>两态自由能开关</strong>，阈值温度由 <strong>ΔG(T) = 0 的温度</strong>定义。单点突变改变局部相互作用，就平移了 ΔH 与 ΔS，从而<strong>把整条激活曲线左右平移</strong>。这是一个<strong>普适的</strong>结论：<strong>凡是由两态平衡控制的功能阈值，都可以被&quot;一个参数&quot;整体标定。</strong></p><p>看生态：渔业的&quot;崩溃&quot;是<strong>另一个阈值</strong>——但注意，<strong>预警信号先于崩溃出现</strong>（生产力骤降早约十年），这对应临界点前的<strong>临界慢化</strong>：系统恢复速率趋近于零，扰动的影响持续得更久（自相关→1），方差升高。于是&quot;<strong>阈值越近，恢复越慢</strong>&quot;成为一个<strong>可测的前兆</strong>。</p><p><strong>统一的第一性原理</strong>：<strong>&quot;哪里最先越界&quot;和&quot;何时越界&quot;由系统的几何与自由能地形共同决定；而越界的不可逆性，恰恰来自越界前恢复速率的下降。</strong> 由此得到两条可证伪预测：（1）<strong>失效区位可被几何设计移动</strong>（改曲率分布）；（2）<strong>任何临近阈值的系统，都应在越界前表现出恢复变慢</strong>（临界慢化的方差/自相关上升），据此可做前置预警。</p><hr><h3 id="原理二-不变性即压缩——-换个读法-为什么等价-以及它为何能带来容量红利" tabindex="-1">原理二：不变性即压缩——&quot;换个读法&quot;为什么等价，以及它为何能带来容量红利 <a class="header-anchor" href="#原理二-不变性即压缩——-换个读法-为什么等价-以及它为何能带来容量红利" aria-label="Permalink to &quot;原理二：不变性即压缩——&quot;换个读法&quot;为什么等价，以及它为何能带来容量红利&quot;">​</a></h3><p>第二组第一性原理关乎<strong>信息</strong>：<strong>把&quot;同一对象的等价重述&quot;识别出来，等于凭空获得压缩。</strong></p><p><strong>CIRPIN（第 4 条）</strong> 是最直白的例子。圆周排列（CP）的蛋白<strong>结构相同、只是起点不同</strong>——用信息论语言，这是同一个折叠的<strong>两种等价表示</strong>。传统结构搜索之所以漏掉 CP，是因为它把<strong>表示（起终点位置）<strong>当成了</strong>对象本身</strong>。CIRPIN 用<strong>合成圆周排列的数据增强</strong>，教会模型一个<strong>对 CP 不变的表示</strong>——即把&quot;起终点&quot;这个<strong>可变（nuisance）维度</strong>从表示里<strong>约掉</strong>。约掉之后，1830 万对原本隐藏的等价关系<strong>立刻显形</strong>。</p><p><strong>KV 缓存量化（第 6 条）</strong> 与 <strong>DI-Bench（第 10 条）</strong> 是同一条原理的工程化版本。量化要解决的，正是**&quot;权值/激活里哪些比特承载的是等价冗余、可以丢弃&quot;<strong>——<strong>KIVI 的逐组元数据</strong>与 <strong>KVQuant 的稀疏离群值</strong>之所以&quot;多花预算&quot;，是因为它们</strong>保留了表示层的特例**（把&quot;何时该特殊对待&quot;也存了下来），而没有把特例<strong>约化为</strong>一个统一的不变结构。DI-Bench 则把&quot;问题—答案&quot;的等价关系<strong>锚定到查询执行</strong>——即用<strong>可在任意表示下复算的不变量</strong>来定义真值，从而不受 LLM 生成措辞的干扰。</p><p><strong>再往上一层</strong>：<strong>来那卡帕韦</strong>的&quot;降低晶格曲率&quot;与<strong>失聪皮层的&quot;重分配&quot;</strong>，同样是在<strong>更大的等价类里</strong>寻找更省资源的表示——前者把药物作用约化为<strong>单一几何参数</strong>（曲率），后者把可塑性约化为<strong>总量守恒下的分配</strong>。</p><p><strong>第一性原理</strong>：<strong>任何&quot;识别不变性&quot;的过程，都是把可变维度从表示中约掉的过程；而每约掉一个冗余维度，就获得一份压缩红利（更小的库、更少的比特、更强的泛化）。</strong> 这是<strong>可证伪的</strong>：若某方法真正抓住了不变性，它应当<strong>对不改变本质的扰动鲁棒</strong>（CP、措辞、表示格式），而<strong>对改变本质的扰动敏感</strong>。凡是声称&quot;不变&quot;却对两种扰动<strong>无差别</strong>的模型，说明它<strong>根本没学到不变性，只是学到了捷径（shortcut）</strong>——这正是 2026 年 AI 评测反复踩到的坑。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期 10 条横跨神经科学、演化—热生物学、病毒学、蛋白质结构、渔业生态与 AI 工程，但它们被<strong>同一条主线</strong>串起：<strong>在固定的资源或结构约束下，&quot;什么能变、什么不能变&quot;决定了系统的行为。</strong></p><ul><li><strong>&quot;阈值&quot;三连</strong>：TRPA1 的热开关（第 2 条）、来那卡帕韦的衣壳断裂（第 3 条）、渔业的生产力骤降（第 5 条）共享 <strong>参数→阈值→质变</strong> 的骨架。三者分属热力学、力学、生态学，却在数学上同构——都是<strong>梯度驱动下越过临界点的不可逆过程</strong>。</li><li><strong>&quot;容量守恒&quot;三连</strong>：失聪皮层的重分配（第 1 条）、KV 缓存的资源分配（第 6 条）、DI-Bench 的基准生成（第 10 条）都在回答**&quot;固定预算怎么花&quot;<strong>。皮层的&quot;总量不变、中央让渡给周边&quot;、NVM 的&quot;存储/旋转/计算三方再分配&quot;、以及基准&quot;用执行锚定真值以省下人工&quot;，本质是同一个</strong>约束优化**。</li><li><strong>&quot;不变性与治理&quot;双连</strong>：CIRPIN 约掉 CP 冗余（第 4 条）、挽具增益的最差保证（第 7 条）、技能维护的人—机分工（第 8 条）、组织偏差正常化（第 9 条）——后三条都在提醒：<strong>系统的可靠不来自&quot;能力&quot;，而来自&quot;约束被持续维护&quot;。</strong> 技能库需要人照看（第 8 条），安全基础设施会被偏差正常化掏空（第 9 条），而第 7 条用一个 95% 下界而不是平均增益来表述承诺——<strong>三者都拒绝用&quot;平均好看&quot;替代&quot;最坏可控&quot;</strong>。</li></ul><p><strong>与库内主题的深层同构。</strong> 本库 <code>topics/ai-brain/index.md</code> 主张&quot;<strong>知识网络而非 RAG</strong>&quot;；本期 CIRPIN（第 4 条）与 DI-Bench（第 10 条）恰好为这一主张补上两个可执行判据：CIRPIN 说明**&quot;识别等价重述&quot;能显形隐藏关联**（这正是本库 <code>links/links.md</code> 想做的事——把&quot;换个写法的同一件事&quot;连起来），DI-Bench 的&quot;<strong>用执行锚定真值</strong>&quot;则对应本库&quot;<strong>每条关联须指向真实存在的文件</strong>&quot;的硬规则。第 8 条（谁维护技能）<strong>直接击中本库自身的运维现实</strong>：<code>topics/ai-brain/knowledge-system-arsenal.md</code> 里维护的技能库，其质量同样取决于<strong>人的触发与治理</strong>，而非自动策展的覆盖率——这为本库的演进方向提供了一个实证注脚：<strong>自动化可以加速，但不能替代人对&quot;偏差是否被正常化&quot;的监督</strong>。</p><p>反向的一点张力：第 9 条警告**&quot;组织的安全边际会被逐步侵蚀&quot;<strong>，而本库每天都在</strong>自动写入、自动关联**——这本身就是一个<strong>可能滑向&quot;偏差正常化&quot;的自动化回路</strong>：若&quot;自动关联&quot;产出的低质量链接无人复核、久而久之被当作常态接受，那么形式上的知识网络就可能<strong>实效上退化</strong>。这正是本期最该被本库记下的一条自省。</p><hr><p>关键词：视网膜拓扑重映射, retinotopic remapping, 失聪, 外侧膝状体, LGN, V1, 神经可塑性, TRPA1, 热激活, 单点突变, SP1, CADM1, MDGA1, 背根神经节, 来那卡帕韦, lenacapavir, HIV-1衣壳, 富勒烯锥, 应力应变模型, CIRPIN, 圆周排列, circular permutation, 图神经网络, CIRPIN-DB, CATH, 渔业生产力, 种群崩溃, 早期预警信号, 临界慢化, KV缓存, 量化, NVM, KIVI, KVQuant, 工具智能体, harness, RelLift95, PRISM, SKILL.md, 技能维护, 偏差正常化, normalization of deviance, DI-Bench, 企业智能体, 10.1073/pnas.2532413123, 10.1126/sciadv.aee3948, 10.1126/sciadv.aed8384, 10.1073/pnas.2605178123, 10.1126/sciadv.aed7911, arXiv:2609.05764, arXiv:2609.05736, arXiv:2609.05677, arXiv:2609.05749, arXiv:2609.05776, 约克大学, 复旦大学, 犹他大学, MIT, ISEM蒙彼利埃, PNAS, Science Advances</p><p>关联：topics/neuroscience/index.md, topics/biomedicine/index.md, topics/physics/index.md, topics/ai-brain/index.md, topics/ai-brain/knowledge-system-arsenal.md, topics/ai-system-architecture/index.md, topics/ai-system-architecture/llm-cache-pricing.md, topics/ai-system-architecture/llm-scaling-limits.md, topics/ai-system-architecture/deepseek-harness-agent-runtime.md, topics/ai-system-architecture/llm-reasoning-verification-thermodynamic.md, topics/ai-system-architecture/bazaar-agentic-commerce.md, topics/ai-system-architecture/ai-industry-2026-q3-knowledge.md, topics/ai-system-architecture/cognitive-atrophy-knowledge.md, topics/ai-system-architecture/brain-self-evolution.md, topics/philosophy/epistemology.md, topics/wind-energy/index.md, topics/cross-domain-synthesis-2026-q3.md</p>',128)])])}const h=o(g,[["render",e]]);export{d as __pageData,h as default};
